158			{"id":"e2","service":"api","severity":"info","message":"ok","at":"2026-10-01T09:00:00Z"}
159		]}`
160		status, out := post(t, server, body)
161		if status != http.StatusOK {
162			t.Fatalf("status=%d body=%v", status, out)
163		}
164		if out["created"].(float64) != 2 || out["replayed"].(float64) != 0 {
165			t.Fatalf("unexpected counts: %v", out)
166		}
167		if len(store.appended) != 1 || store.appended[0] != 2 {
168			t.Fatalf("expected one durable batch of 2, got %v", store.appended)
169		}
170	
171		// Identical retry (same instant expressed in UTC) is fully replayed.
172		retry := `{"events":[{"id":"e1","service":"gateway","severity":"critical","message":"spike","at":"2026-10-01T02:00:00.123456789Z"}]}`
173		status, out = post(t, server, retry)
174		if status != http.StatusOK {
175			t.Fatalf("retry status=%d body=%v", status, out)
176		}
177		if out["created"].(float64) != 0 || out["replayed"].(float64) != 1 {
178			t.Fatalf("retry counts: %v", out)
179		}
180		if len(store.appended) != 1 {
181			t.Fatal("replay must not touch storage")
182		}
183	
184		status, rows := get(t, server, "")
185		arr := rows.([]any)
186		if status != http.StatusOK || len(arr) != 2 {
187			t.Fatalf("get: status=%d rows=%v", status, arr)
188		}
189		// e1 is 10:00+08 == 02:00 UTC, so it precedes e2 at 09:00 UTC.
190		first := arr[0].(map[string]any)
191		if first["id"] != "e1" || first["severity"] != "critical" || first["message"] != "spike" {
192			t.Fatalf("ordering/normalization wrong: %v", first)
193		}
194		if got := arr[1].(map[string]any)["at"]; got != "2026-10-01T09:00:00Z" {
195			t.Fatalf("second row timestamp: %v", got)
196		}
197	}
