13	// bigLtCount is a run of '<' large enough that its saved encoding escapes
14	// past the 64 MiB save capacity, while the literal characters keep the
15	// request body under the 16 MiB body limit (each '<' is one request byte but
16	// six saved bytes).
17	const bigLtCount = 11_200_000
18	
19	func oversizeEventBody(id, at string) string {
20		return `{"events":[{"id":"` + id + `","service":"svc","severity":"info","message":"` +
21			strings.Repeat("<", bigLtCount) + `","at":"` + at + `"}]}`
22	}
23	
24	// TestServeOversizeBatchIs400AndStaysUsable is the end-to-end form of the
25	// reported bug: a legal, sub-16-MiB request that saves to over 64 MiB is a
26	// 400 (send less content), not a 503 (storage failed, restart). The rejected
27	// batch leaves no durable record, the server keeps accepting batches with no
28	// restart, and the rejected id is free on the same process and after a
29	// kill/recovery cycle.
30	func TestServeOversizeBatchIs400AndStaysUsable(t *testing.T) {
31		dataDir := t.TempDir()
32		p := startServer(t, dataDir)
33		body := oversizeEventBody("huge", "2026-10-01T09:00:00Z")
34		if len(body) >= 16<<20 {
35			t.Fatalf("setup: request body %d exceeds the 16 MiB body limit", len(body))
36		}
37	
38		status, raw := httpDo(t, http.MethodPost, "http://"+p.addr+"/events", body)
39		if status != http.StatusBadRequest {
40			t.Fatalf("oversize batch must be 400, got %d: %s", status, truncate(raw))
41		}
42		var errBody map[string]string
43		if err := json.Unmarshal(raw, &errBody); err != nil {
44			t.Fatalf("decode error body %q: %v", raw, err)
45		}
46		msg := errBody["error"]
47		if msg == "" {
48			t.Fatal("error must be non-empty")
49		}
50		if !strings.Contains(msg, "save capacity") && !strings.Contains(strings.ToLower(msg), "reduce") {
51			t.Fatalf("error must point at the save capacity / sending less, got %q", msg)
52		}
53		if strings.Contains(strings.ToLower(msg), "restart") {
54			t.Fatalf("oversize error must not demand a restart, got %q", msg)
55		}
56	
57		// Nothing from the rejected batch is queryable.
58		if got := getEvents(t, p, "?service=svc"); len(got) != 0 {
59			t.Fatalf("rejected events must not be visible, got %d", len(got))
60		}
61	
62		// The store is still usable with no restart: a normal batch commits.
63		normal := `{"events":[{"id":"ok","service":"svc","severity":"info","message":"fine","at":"2026-10-01T09:01:00Z"}]}`
64		if counts := postEvents(t, p, normal); counts["created"] != 1 {
65			t.Fatalf("normal batch after rejection: %v", counts)
66		}
67	
68		// The rejected id is reusable right away in a smaller batch.
69		reuse := `{"events":[{"id":"huge","service":"svc","severity":"info","message":"tiny","at":"2026-10-01T09:02:00Z"}]}`
70		if counts := postEvents(t, p, reuse); counts["created"] != 1 {
71			t.Fatalf("rejected id must be reusable: %v", counts)
72		}
73	
74		// Kill without graceful shutdown; on recovery only the two accepted
75		// events may be present — the rejected batch must have left no frame.
76		p.signal(t, syscall.SIGKILL)
77		p.waitExit(t, -1)
78		waitTCPPortClosed(t, p.addr)
79	
80		if onDisk, err := os.ReadFile(filepath.Join(dataDir, "events.log")); err != nil {
81			t.Fatalf("read events log: %v", err)
82		} else if strings.Count(string(onDisk), `"huge"`) != 1 {
83			// One accepted frame now carries the small "huge" retry; the
84			// oversize message never landed, so there must be no second hit.
85			t.Fatalf("rejected batch left a durable record (huge hits=%d)", strings.Count(string(onDisk), `"huge"`))
86		}
87	
88		p2 := startServer(t, dataDir)
89		got := getEvents(t, p2, "?service=svc")
90		if len(got) != 2 {
91			t.Fatalf("after recovery want the 2 accepted events, got %d: %+v", len(got), got)
92		}
93		// Reusing the id again after restart is a replay, not a conflict.
94		if counts := postEvents(t, p2, reuse); counts["created"] != 0 || counts["replayed"] != 1 {
95			t.Fatalf("rejected-then-accepted id must replay after restart: %v", counts)
96		}
97		p2.signal(t, syscall.SIGTERM)
98		p2.waitExit(t, 0)
99	}
100	
101	func truncate(b []byte) string {
102		const max = 200
103		if len(b) <= max {
104			return string(b)
105		}
106		return string(b[:max]) + "..."
107	}
