192	func TestPostMetricsFailurePoisonsOnlyMetrics(t *testing.T) {
193		mstore := &fakeMetricStorage{failNext: true}
194		server := newMetricsServer(t, metrics.NewStore(), mstore)
195	
196		status, _ := metricsDo(t, server, http.MethodPost, "/metrics",
197			`{"samples":[{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`)
198		if status != http.StatusServiceUnavailable {
