546	// windowCount runs an aggregate query expected to match exactly one series
547	// and returns the number of samples in its segments. It is the queryable
548	// evidence that ingestion stored (or did not store) a point.
549	func windowCount(t *testing.T, server *httptest.Server, query string) int {
550		t.Helper()
551		status, out := aggregateGet(t, server, query)
552		if status != http.StatusOK || len(out) != 1 {
553			t.Fatalf("aggregate expected one series, got %d: %v", status, out)
554		}
555		total := 0
556		for _, seg := range out[0]["segments"].([]any) {
557			total += int(number(seg.(map[string]any)["count"]))
558		}
559		return total
560	}
