14	// putFrame writes the shared length-prefixed, CRC-checked frame layout into a
15	// buffer sized for one payload.
16	func putFrame(frame, payload []byte) {
17		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
18		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
19		copy(frame[8:], payload)
20	}
21	
22	func postMetrics(t *testing.T, p *serverProc, body string) map[string]int {
23		t.Helper()
24		status, raw := httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", body)
25		if status >= 400 {
26			t.Fatalf("POST /metrics status %d: %s", status, raw)
27		}
28		var out map[string]int
29		if err := json.Unmarshal(raw, &out); err != nil {
30			t.Fatal(err)
31		}
32		return out
33	}
34	
35	func metricAggregate(t *testing.T, p *serverProc, query string) (int, []map[string]any) {
36		t.Helper()
37		status, raw := httpDo(t, http.MethodGet, "http://"+p.addr+"/metrics/aggregate"+query, "")
38		if status >= 400 {
39			var errBody map[string]any
40			_ = json.Unmarshal(raw, &errBody)
41			return status, []map[string]any{{"_error": errBody}}
42		}
43		var out []map[string]any
44		if err := json.Unmarshal(raw, &out); err != nil {
45			t.Fatalf("decode %q: %v", raw, err)
46		}
47		return status, out
48	}
49	
50	const sampleMetrics = `{"samples":[
51		{"id":"m1","service":"gateway","name":"requests","at":"2026-10-01T10:00:00Z","value":100},
52		{"id":"m2","service":"gateway","name":"requests","at":"2026-10-01T10:01:00Z","value":105}
53	]}`
54	
55	func TestServeMetricsPersistAcrossKillAndDedupeRetry(t *testing.T) {
56		dataDir := t.TempDir()
57		p := startServer(t, dataDir)
58		if counts := postMetrics(t, p, sampleMetrics); counts["created"] != 2 {
59			t.Fatalf("created=%v", counts)
60		}
61	
62		p.signal(t, syscall.SIGKILL)
63		p.waitExit(t, -1)
64		waitTCPPortClosed(t, p.addr)
65	
66		p2 := startServer(t, dataDir)
67		status, got := metricAggregate(t, p2,
68			"?name=requests&since=2026-10-01T10:00:00Z&until=2026-10-01T10:02:00Z&step=60")
69		if status != http.StatusOK {
70			t.Fatalf("aggregate after restart: %d %v", status, got)
71		}
72		if len(got) != 1 {
73			t.Fatalf("one series: %v", got)
74		}
75		segments := got[0]["segments"].([]any)
76		if segments[0].(map[string]any)["delta"].(float64) != 0 ||
77			segments[1].(map[string]any)["delta"].(float64) != 5 {
78			t.Fatalf("deltas must survive restart: %v", segments)
79		}
80	
81		// The identical batch replays with zero created.
82		if counts := postMetrics(t, p2, sampleMetrics); counts["created"] != 0 || counts["replayed"] != 2 {
83			t.Fatalf("retry after restart: %v", counts)
84		}
85		p2.signal(t, syscall.SIGTERM)
86		p2.waitExit(t, 0)
87	}
88	
89	// postMetricsExpectError runs a POST /metrics that must fail with the given
90	// status and a non-empty error field.
91	func postMetricsExpectError(t *testing.T, p *serverProc, wantStatus int, body string) {
92		t.Helper()
93		status, raw := httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", body)
94		if status != wantStatus {
95			t.Fatalf("POST /metrics: want %d, got %d: %s", wantStatus, status, raw)
96		}
97		var errBody map[string]string
98		if err := json.Unmarshal(raw, &errBody); err != nil || errBody["error"] == "" {
99			t.Fatalf("status %d must carry a non-empty error, got %s", status, raw)
100		}
101	}
102	
103	// windowSampleCount aggregates one query expected to match exactly one series
104	// and returns the number of samples across its segments.
105	func windowSampleCount(t *testing.T, p *serverProc, query string) int {
106		t.Helper()
107		status, series := metricAggregate(t, p, query)
108		if status != http.StatusOK || len(series) != 1 {
109			t.Fatalf("aggregate %s: want one series, got %d %v", query, status, series)
110		}
111		segments := series[0]["segments"].([]any)
112		total := 0
113		for _, segment := range segments {
114			total += int(segment.(map[string]any)["count"].(float64))
115		}
116		return total
117	}
118	
119	// TestServeMetricsWideDateSamplesAcceptedAcrossEras is the acceptance
120	// guarantee for sampling-instant identity far outside the years for which
121	// time.Time.UnixNano stays exact. The two instants share one naive UnixNano
122	// value, so they must still be received as two distinct points in either
123	// submission order, survive a timezone-only retry as a replay, and remain
124	// independently queryable; a legal post-2262 date is accepted too.
125	func TestServeMetricsWideDateSamplesAcceptedAcrossEras(t *testing.T) {
126		const (
127			oldAt    = "1600-01-01T00:00:00Z"
128			oldAltTZ = "1600-01-01T08:00:00+08:00" // same absolute instant as oldAt
129			futureAt = "2184-07-20T23:34:33.709551616Z"
130		)
131		oldWindow := "?name=requests&service=gateway&since=1599-12-31T23:59:59Z&until=1600-01-01T00:00:01Z&step=2"
132		futureWindow := "?name=requests&service=gateway&since=2184-07-20T23:34:33Z&until=2184-07-20T23:34:34Z&step=1"
133	
134		for _, reverse := range []bool{false, true} {
135			t.Run("order", func(t *testing.T) {
136				p := startServer(t, t.TempDir())
137				body := `{"samples":[
138					{"id":"era-old","service":"gateway","name":"requests","at":"` + oldAt + `","value":1},
139					{"id":"era-new","service":"gateway","name":"requests","at":"` + futureAt + `","value":2}
140				]}`
141				if reverse {
142					body = `{"samples":[
143						{"id":"era-new","service":"gateway","name":"requests","at":"` + futureAt + `","value":2},
144						{"id":"era-old","service":"gateway","name":"requests","at":"` + oldAt + `","value":1}
145					]}`
146				}
147				if counts := postMetrics(t, p, body); counts["created"] != 2 || counts["replayed"] != 0 {
148					t.Fatalf("distant legal dates must both be new (reverse=%v): %v", reverse, counts)
149				}
150	
151				if count := windowSampleCount(t, p, oldWindow); count != 1 {
152					t.Fatalf("old-era window must contain its one point, got %d (reverse=%v)", count, reverse)
153				}
154				if count := windowSampleCount(t, p, futureWindow); count != 1 {
155					t.Fatalf("future-era window must contain its one point, got %d (reverse=%v)", count, reverse)
156				}
157	
158				// The identical batch retries entirely as replays.
159				if counts := postMetrics(t, p, body); counts["created"] != 0 || counts["replayed"] != 2 {
160					t.Fatalf("identical batch must replay (reverse=%v): %v", reverse, counts)
161				}
162	
163				// Same id, same content, only the timezone spelling differs: one
164				// replay, no added sample.
165				if counts := postMetrics(t, p, `{"samples":[
166					{"id":"era-old","service":"gateway","name":"requests","at":"`+oldAltTZ+`","value":1}
167				]}`); counts["created"] != 0 || counts["replayed"] != 1 {
168					t.Fatalf("timezone-only resubmission must replay one: %v", counts)
169				}
