172				}
173				if count := windowSampleCount(t, p, futureWindow); count != 1 {
174					t.Fatalf("replay must not increase the future-era count, got %d", count)
175				}
176				p.signal(t, syscall.SIGTERM)
177				p.waitExit(t, 0)
178			})
179		}
