197	// TestServeMetricsWideDateConflictsRejectWholeBatch covers the clash rules at
198	// distant dates: another timezone spelling is the same sampling point, a
199	// different id cannot occupy it either against stored data or inside one
200	// batch, mixed batches roll back completely, and the legal sample from a
201	// rejected batch still ingests when sent alone.
202	func TestServeMetricsWideDateConflictsRejectWholeBatch(t *testing.T) {
203		const (
204			oldAt        = "1600-01-01T00:00:00Z"
205			oldAltTZ     = "1600-01-01T08:00:00+08:00"
206			futureAt     = "2184-07-20T23:34:33.709551616Z"
207			futureAltTZ  = "2184-07-20T16:34:33.709551616-07:00" // same instant as futureAt
208			futureNextNS = "2184-07-20T23:34:33.709551617Z"      // one nanosecond later
209		)
210		oldWindow := "?name=requests&service=gateway&since=1599-12-31T23:59:59Z&until=1600-01-01T00:00:01Z&step=2"
211		futureWindow := "?name=requests&service=gateway&since=2184-07-20T23:34:33Z&until=2184-07-20T23:34:34Z&step=1"
212	
213		p := startServer(t, t.TempDir())
214		if counts := postMetrics(t, p, `{"samples":[
215			{"id":"owner","service":"gateway","name":"requests","at":"`+oldAt+`","value":1}
216		]}`); counts["created"] != 1 {
217			t.Fatalf("seed: %v", counts)
218		}
219	
220		// Clash with an already-accepted point via another timezone spelling.
221		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
222			{"id":"intruder","service":"gateway","name":"requests","at":"`+oldAltTZ+`","value":5}
223		]}`)
224	
225		// Same absolute future instant under two offsets inside one batch.
226		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
227			{"id":"f1","service":"gateway","name":"requests","at":"`+futureAt+`","value":1},
228			{"id":"f2","service":"gateway","name":"requests","at":"`+futureAltTZ+`","value":2}
229		]}`)
230	
231		// One conflicting sample plus one legal new sample: the whole batch is
232		// refused, with nothing left behind.
233		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
234			{"id":"intruder2","service":"gateway","name":"requests","at":"`+oldAltTZ+`","value":9},
235			{"id":"fresh","service":"gateway","name":"requests","at":"`+futureNextNS+`","value":3}
236		]}`)
237		if count := windowSampleCount(t, p, oldWindow); count != 1 {
238			t.Fatalf("rollback must leave the old era unchanged, got %d", count)
239		}
240		if status, series := metricAggregate(t, p, futureWindow); status != http.StatusOK || len(series) != 0 {
241			t.Fatalf("legal sample must not survive the rollback, got %d %v", status, series)
242		}
