244		// The legal new sample sent on its own really is new.
245		if counts := postMetrics(t, p, `{"samples":[
246			{"id":"fresh","service":"gateway","name":"requests","at":"`+futureNextNS+`","value":3}
247		]}`); counts["created"] != 1 || counts["replayed"] != 0 {
248			t.Fatalf("standalone legal sample must create one: %v", counts)
249		}
