271	// coexistence and the series scoping of clashes at a distant date: samples
272	// differing by even one nanosecond coexist, while clashes stay confined to
273	// the identical label set.
274	func TestServeMetricsNanosecondAndLabelIdentity(t *testing.T) {
275		p := startServer(t, t.TempDir())
276	
277		// Two samples one nanosecond apart in the same second are both new.
