291			{"id":"ns0","service":"gateway","name":"requests","at":"2026-10-01T18:00:00.111111111+08:00","value":1}
292		]}`); counts["created"] != 0 || counts["replayed"] != 1 {
293			t.Fatalf("timezone-only retry must replay one: %v", counts)
294		}
