310			{"id":"lp","service":"gateway","name":"requests","at":"1600-01-01T00:00:00Z","value":1,"labels":{"env":"prod"}},
311			{"id":"ls","service":"gateway","name":"requests","at":"1600-01-01T00:00:00Z","value":1,"labels":{"env":"staging"}}
312		]}`); counts["created"] != 2 || counts["replayed"] != 0 {
