		{"id":"e2","service":"s","severity":"info","message":"m","at":"2026-10-01T09:01:00Z"}
	]}`)

	_, out := pageGet(t, p1, "?limit=1")
	if out.NextCursor == nil {
		t.Fatal("expected a next_cursor")
