	_, out = pageGet(t, p2, "?limit=1&cursor="+*out.NextCursor)
	if len(out.Events) != 1 || out.Events[0]["id"] != "e2" {
		t.Fatalf("old cursor must not see post-restart event: %v", out.Events)
	}
	p2.signal(t, syscall.SIGTERM)
	p2.waitExit(t, 0)
}

