	next := Sample{ID: "ok", Service: "gw", Name: "requests", At: base.Add(2 * time.Second), Value: 1}
	if _, err := store.Ingest([]Sample{next}, noopCommit); err != nil {
		t.Fatalf("store must remain usable after oversize rejection: %v", err)
	}
